      <?php elseif ($page === 'reports'): ?>
        <?php
        $income = (float) db()->query("SELECT COALESCE(SUM(amount), 0) FROM Payment WHERE status = 'อนุมัติ' AND DATE_FORMAT(paymentDate, '%Y-%m') = DATE_FORMAT(CURRENT_DATE(), '%Y-%m')")->fetchColumn();
        $due = db()->query("SELECT r.roomNumber, u.name, r.rentalPrice FROM Contract c JOIN Room r ON r.roomId = c.roomId JOIN `User` u ON u.userId = c.userId WHERE c.status = 'ใช้งานอยู่' ORDER BY r.roomNumber")->fetchAll();
        $balances = db()->query("SELECT r.roomNumber, u.name,
            COALESCE((SELECT SUM(i.rentAmount + i.waterUnit * i.waterRate + i.electricUnit * i.electricRate) FROM Invoice i WHERE i.contractId = c.contractId AND i.status = 'รอชำระ'), 0)
            + COALESCE((SELECT SUM(f.amount) FROM Fine f WHERE f.contractId = c.contractId AND f.status = 'รอชำระ'), 0) AS balance
            FROM Contract c JOIN Room r ON r.roomId = c.roomId JOIN `User` u ON u.userId = c.userId
            WHERE c.status = 'ใช้งานอยู่' HAVING balance > 0 ORDER BY r.roomNumber")->fetchAll();
        $reportRepairs = db()->query('SELECT repairStatus, COUNT(*) AS total FROM Repair GROUP BY repairStatus ORDER BY total DESC')->fetchAll();
        $recentRepairs = db()->query("SELECT rp.repairDate, rp.repairStatus, rp.detail, r.roomNumber, u.name
            FROM Repair rp JOIN Room r ON r.roomId = rp.roomId JOIN `User` u ON u.userId = rp.userId
            WHERE rp.repairDate >= DATE_SUB(CURRENT_DATE(), INTERVAL 6 DAY)
            ORDER BY rp.repairDate DESC, rp.repairId DESC")->fetchAll();
        $todayRepairs = db()->query("SELECT rp.repairDate, rp.repairStatus, rp.detail, r.roomNumber, u.name
            FROM Repair rp JOIN Room r ON r.roomId = rp.roomId JOIN `User` u ON u.userId = rp.userId
            WHERE rp.repairDate = CURRENT_DATE()
            ORDER BY rp.repairId DESC")->fetchAll();
        $roomSummary = db()->query('SELECT roomStatus, COUNT(*) AS total FROM Room GROUP BY roomStatus')->fetchAll();
        ?>
        <section class="page-heading"><div><p class="eyebrow">OPERATIONS REPORT</p><h1>รายงานสรุป</h1><p class="muted">ข้อมูลภาพรวมรายรับ ห้องพัก ยอดค้าง และงานซ่อม</p></div><span class="period-chip">เดือนนี้ · <?= e(date('m/Y')) ?></span></section>
        <section class="metric-grid"><article class="metric-card"><div class="metric-top"><span>รายรับที่อนุมัติเดือนนี้</span><span class="metric-icon mint">฿</span></div><strong><?= money($income) ?> ฿</strong><small>รวมรายการชำระที่อนุมัติแล้ว</small></article><article class="metric-card"><div class="metric-top"><span>ห้องที่มีสัญญาใช้งาน</span><span class="metric-icon blue">♙</span></div><strong><?= count($due) ?></strong><small>ผู้เช่าปัจจุบัน</small></article><article class="metric-card"><div class="metric-top"><span>ยอดค้างชำระรวม</span><span class="metric-icon orange">฿</span></div><strong><?= money(array_sum(array_column($balances, 'balance'))) ?> ฿</strong><small><?= count($balances) ?> ห้องมีรายการค้าง</small></article><article class="metric-card"><div class="metric-top"><span>รายการแจ้งซ่อม</span><span class="metric-icon orange">⌕</span></div><strong><?= array_sum(array_column($reportRepairs, 'total')) ?></strong><small>รายการทั้งหมด</small></article><article class="metric-card"><div class="metric-top"><span>ห้องพักทั้งหมด</span><span class="metric-icon blue">⌂</span></div><strong><?= array_sum(array_column($roomSummary, 'total')) ?></strong><small>ทุกสถานะห้อง</small></article></section>
        <section class="dashboard-grid"><article class="panel"><div class="panel-heading"><div><p class="eyebrow">ROOM STATUS</p><h2>สถานะห้องพัก</h2></div></div><?php foreach ($roomSummary as $status): ?><div class="summary-row"><span><?= e($status['roomStatus']) ?></span><strong><?= e((string) $status['total']) ?> ห้อง</strong></div><?php endforeach; ?></article><article class="panel"><div class="panel-heading"><div><p class="eyebrow">REPAIR STATUS</p><h2>สถานะงานซ่อม</h2></div></div><?php foreach ($reportRepairs as $status): ?><div class="summary-row"><span><?= e($status['repairStatus']) ?></span><strong><?= e((string) $status['total']) ?> งาน</strong></div><?php endforeach; ?></article></section>
        <section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">OUTSTANDING BY ROOM</p><h2>ยอดค้างชำระรายห้อง</h2></div></div><div class="table-scroll"><table><thead><tr><th>ห้อง</th><th>ผู้เช่า</th><th>ยอดค้างชำระ</th></tr></thead><tbody><?php foreach ($balances as $balance): ?><tr><td><?= e($balance['roomNumber']) ?></td><td><?= e($balance['name']) ?></td><td><strong><?= money($balance['balance']) ?> ฿</strong></td></tr><?php endforeach; ?></tbody></table><?php if (!$balances): ?><div class="empty-state compact"><strong>ไม่มีรายการค้างชำระ</strong></div><?php endif; ?></div></section>
        <section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">REPAIR REQUESTS · TODAY</p><h2>รายการแจ้งซ่อมประจำวัน</h2></div><span class="panel-caption"><?= count($todayRepairs) ?> รายการ</span></div><div class="table-scroll"><table><thead><tr><th>วันที่</th><th>ห้อง</th><th>ผู้แจ้ง</th><th>รายละเอียด</th><th>สถานะ</th></tr></thead><tbody><?php foreach ($todayRepairs as $repair): ?><tr><td><?= e(date('d/m/Y', strtotime($repair['repairDate']))) ?></td><td><?= e($repair['roomNumber']) ?></td><td><?= e($repair['name']) ?></td><td><?= e(mb_strimwidth($repair['detail'], 0, 100, '...', 'UTF-8')) ?></td><td><?= e($repair['repairStatus']) ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$todayRepairs): ?><div class="empty-state compact"><strong>ไม่มีรายการแจ้งซ่อมวันนี้</strong></div><?php endif; ?></div></section>
        <section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">REPAIR REQUESTS · LAST 7 DAYS</p><h2>รายการแจ้งซ่อมประจำสัปดาห์</h2></div><span class="panel-caption"><?= count($recentRepairs) ?> รายการ</span></div><div class="table-scroll"><table><thead><tr><th>วันที่</th><th>ห้อง</th><th>ผู้แจ้ง</th><th>รายละเอียด</th><th>สถานะ</th></tr></thead><tbody><?php foreach ($recentRepairs as $repair): ?><tr><td><?= e(date('d/m/Y', strtotime($repair['repairDate']))) ?></td><td><?= e($repair['roomNumber']) ?></td><td><?= e($repair['name']) ?></td><td><?= e(mb_strimwidth($repair['detail'], 0, 100, '...', 'UTF-8')) ?></td><td><?= e($repair['repairStatus']) ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$recentRepairs): ?><div class="empty-state compact"><strong>ไม่มีรายการแจ้งซ่อมใน 7 วันที่ผ่านมา</strong></div><?php endif; ?></div></section>
        <section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">ACTIVE LEASES</p><h2>สัญญาเช่าที่ใช้งานอยู่</h2></div></div><div class="table-scroll"><table><thead><tr><th>ห้อง</th><th>ผู้เช่า</th><th>ค่าเช่าต่อเดือน</th></tr></thead><tbody><?php foreach ($due as $lease): ?><tr><td><?= e($lease['roomNumber']) ?></td><td><?= e($lease['name']) ?></td><td><?= money($lease['rentalPrice']) ?> ฿</td></tr><?php endforeach; ?></tbody></table></div></section>
